"background:#C4B89A\"></span>个人资料</a>\n    </div>\n    <div class=\"sidebar-section\"><div class=\"sidebar-section-label\">Admin</div>\n      <a href=\"channels.html\" class=\"sidebar-item active\"><span class=\"dot\" style=\"background:#E8702A\"></span>渠道管理</a>\n      <a href=\"models-mgmt.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#6BAFDF\"></span>模型管理</a>\n      <a href=\"users-mgmt.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#4DB899\"></span>用户管理</a>\n      <a href=\"settings.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#C4B89A\"></span>系统设置</a>\n    </div>\n  </aside>\n\n  <!-- MAIN -->\n  <div class=\"main-area\">\n    <div class=\"topbar\">\n      <button class=\"topbar-toggle\" onclick=\"document.getElementById('sidebar').classList.toggle('collapsed')\">☰</button>\n      <span class=\"topbar-brand brand-scan\">幻 MIRAX API</span> <a href=\"index.html\" style=\"font-size:11px;color:rgba(0,0,0,0.4);text-decoration:none;font-weight:500\">← 首页</a>\n      <div style=\"margin-left:auto;display:flex;gap:8px\"><a href=\"settings.html\" class=\"quick-btn\">设置</a><a href=\"profile.html\" class=\"quick-btn\">个人</a></div>\n    </div>\n\n    <div class=\"page\">\n      <div class=\"page-header\">\n        <h1 class=\"page-title\">渠道管理</h1>\n        <div style=\"display:flex;gap:8px\">\n          <button class=\"quick-btn\" id=\"tagMode\">标签模式</button>\n          <button class=\"quick-btn\">+ 创建渠道</button>\n        </div>\n      </div>\n\n      <!-- filters -->\n      <div style=\"display:flex;gap:10px;margin-bottom:16px;align-items:center;flex-wrap:wrap\">\n        <input class=\"filter-input\" placeholder=\"搜索…\">\n        <input class=\"filter-input\" placeholder=\"模型筛选…\">\n        <select class=\"filter-input\" style=\"width:120px\"><option>全部状态</option><option>已启用</option><option>已禁用</option></select>\n        <select class=\"filter-input\" style=\"width:120px\"><option>全部类型</option><option>OpenAI</option><option>Anthropic</option><option>Gemini</option><option>DeepSeek</option></select>\n        <span style=\"font-size:11px;color:rgba(0,0,0,0.3);margin-left:auto\">3 个渠道</span>\n      </div>\n\n      <div class=\"card-sm\" style=\"padding:0;overflow-x:auto\">\n        <table style=\"width:100%;border-collapse:collapse;font-size:12px;min-width:1000px\">\n          <thead>\n            <tr style=\"border-bottom:1px solid rgba(0,0,0,0.06);text-align:left\">\n              <th style=\"padding:10px 8px;width:28px\"><input type=\"checkbox\"></th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">ID</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">名称</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">类型</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">状态</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">模型</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">分组</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">优先级</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">权重</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">余额</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">响应</th>\n              <th style=\"padding:10px 8px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">操作</th>\n            </tr>\n          </thead>\n          <tbody id=\"tbody\"></tbody>\n        </table>\n      </div>\n      <div style=\"display:flex;justify-content:center;gap:6px;margin-top:16px;align-items:center\">\n        <button class=\"quick-btn\">上一页</button><button class=\"quick-btn active\">1</button><button class=\"quick-btn\">下一页</button>\n      </div>\n    </div>\n  </div>\n</div>",
