      "const data=[{id:1,name:'OpenAI 主渠道',type:'OpenAI',status:'enabled',models:['gpt-5.5','gpt-5.5-instant'],groups:['default','premium'],priority:10,weight:1,balance:'$5,234',response:342},{id:2,name:'Anthropic 备用',type:'Anthropic',status:'enabled',models:['claude-opus-4-7','claude-sonnet-4-6'],groups:['default'],priority:8,weight:1,balance:'$2,100',response:568},{id:3,name:'Gemini 测试',type:'Google Gemini',status:'disabled',models:['gemini-3.1-pro'],groups:['test'],priority:5,weight:2,balance:'$0',response:0}];\ndocument.getElementById('tbody').innerHTML=data.map(c=>`<tr style=\"border-bottom:1px solid rgba(0,0,0,0.03)\"><td style=\"padding:10px 8px\"><input type=\"checkbox\"></td><td style=\"padding:10px 8px;font-family:'JetBrains Mono',monospace;font-size:11px;color:rgba(0,0,0,0.4)\">${c.id}</td><td style=\"padding:10px 8px;font-weight:600\">${c.name}</td><td style=\"padding:10px 8px\"><span class=\"badge\" style=\"background:rgba(0,0,0,0.04);color:rgba(0,0,0,0.5)\">${c.type}</span></td><td style=\"padding:10px 8px\"><span class=\"status-dot\" style=\"background:${c.status==='enabled'?'#4DB899':'#E8702A'}\"></span>${c.status==='enabled'?'运行中':'已禁用'}</td><td style=\"padding:10px 8px\">${c.models.map(m=>`<span class=\"badge\" style=\"background:rgba(107,175,223,0.06);color:#6BAFDF;margin-right:3px\">${m}</span>`).join('')}</td><td style=\"padding:10px 8px\">${c.groups.map(g=>`<span class=\"badge\" style=\"background:rgba(0,0,0,0.03);color:rgba(0,0,0,0.45);margin-right:3px\">${g}</span>`).join('')}</td><td style=\"padding:10px 8px;font-family:'JetBrains Mono',monospace;font-size:11px\">${c.priority}</td><td style=\"padding:10px 8px;font-family:'JetBrains Mono',monospace;font-size:11px\">${c.weight}</td><td style=\"padding:10px 8px;font-family:'JetBrains Mono',monospace;font-size:11px\">${c.balance}</td><td style=\"padding:10px 8px;font-family:'JetBrains Mono',monospace;font-size:11px;color:${!c.response?'rgba(0,0,0,0.4)':c.response<500?'#4DB899':'#E8702A'}\">${c.response?c.response+'ms':'-'}</td><td style=\"padding:10px 8px;display:flex;gap:4px\"><button class=\"quick-btn\" style=\"padding:3px 8px;font-size:10px\">编辑</button><button class=\"quick-btn\" style=\"padding:3px 8px;font-size:10px\">测试</button></td></tr>`).join('');"
