    "title": "登录 — 幻 MIRAX API",
    "html": "<style>.input{width:100%;padding:14px 16px;border:1px solid rgba(0,0,0,0.1);border-radius:12px;font-size:15px;font-family:inherit;box-sizing:border-box;outline:none;transition:border-color 0.3s}.input:focus{border-color:#6BAFDF}.oauth-btn{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;padding:12px;border:1px solid rgba(0,0,0,0.08);border-radius:12px;font-size:14px;font-weight:500;cursor:pointer;background:#fff;transition:all 0.3s}.oauth-btn:hover{background:rgba(0,0,0,0.02);border-color:rgba(0,0,0,0.15)}</style>\n<nav class=\"nav\" style=\"color:#1a1815;background:#fafaf9;border-bottom:1px solid rgba(0,0,0,0.04)\">\n  <div class=\"nav-logo\"><a href=\"index.html\" style=\"color:inherit;text-decoration:none\">幻 MIRAX API</a></div>\n  <div class=\"nav-links\">\n    <a href=\"about.html\" class=\"nav-link\">文档</a>\n    <a href=\"pricing.html\" class=\"nav-link\">定价</a>\n    <a href=\"rankings.html\" class=\"nav-link\">排行</a>\n    <a href=\"dashboard.html\" class=\"nav-link\">控制台</a>\n    <a href=\"sign-in.html\" class=\"nav-btn\" style=\"color:#1a1815;border-color:#1a1815\">登录</a>\n  </div>\n</nav>\n\n<div style=\"min-height:100vh;display:flex;align-items:center;justify-content:center;padding:100px 20px 40px;box-sizing:border-box\">\n  <div class=\"shape\" style=\"width:400px;height:400px;background:#6BAFDF;top:-10%;left:-15%\"></div>\n  <div class=\"shape\" style=\"width:350px;height:350px;background:#4DB899;bottom:-10%;right:-12%\"></div>\n\n  <div class=\"card\" style=\"width:400px;max-width:100%;position:relative;z-index:2;padding:40px\">\n    <h1 style=\"font-family:'Noto Serif SC','Playfair Display',Georgia,serif;font-size:28px;font-weight:700;margin:0 0 8px;text-align:center\">登录</h1>\n    <p style=\"text-align:center;font-size:14px;color:rgba(0,0,0,0.45);margin:0 0 32px\">欢迎回到 幻 MIRAX API</p>\n\n    <div style=\"display:flex;flex-direction:column;gap:16px;margin-bottom:24px\">\n      <input class=\"input\" type=\"email\" placeholder=\"邮箱地址\">\n      <input class=\"input\" type=\"password\" placeholder=\"密码\">\n      <button class=\"btn btn-dark\" style=\"justify-content:center;cursor:pointer;border:none;font-size:15px;font-weight:600\">登录</button>\n    </div>\n\n    <div style=\"display:flex;align-items:center;gap:16px;margin-bottom:24px\">\n      <div style=\"flex:1;height:1px;background:rgba(0,0,0,0.06)\"></div>\n      <span style=\"font-size:12px;color:rgba(0,0,0,0.3)\">或</span>\n      <div style=\"flex:1;height:1px;background:rgba(0,0,0,0.06)\"></div>\n    </div>\n\n    <div style=\"display:flex;flex-direction:column;gap:10px;margin-bottom:24px\">\n      <button class=\"oauth-btn\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"#1a1815\"><path d=\"M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z\"/></svg>GitHub</button>\n      <button class=\"oauth-btn\"><svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"#5865F2\"><path d=\"M20.317 4.37a19.791 19.791 0 00-4.885-1.515.074.074 0 00-.079.037c-.21.375-.444.864-.608 1.25a18.27 18.27 0 00-5.487 0 12.64 12.64 0 00-.617-1.25.077.077 0 00-.079-.037A19.736 19.736 0 003.677 4.37a.07.07 0 00-.032.027C.533 9.046-.32 13.58.099 18.057a.082.082 0 00.031.057 19.9 19.9 0 005.993 3.03.078.078 0 00.084-.028 14.09 14.09 0 001.226-1.994.076.076 0 00-.041-.106 13.107 13.107 0 01-1.872-.892.077.077 0 01-.008-.128 10.2 10.2 0 00.372-.292.074.074 0 01.077-.01c3.928 1.793 8.18 1.793 12.062 0a.074.074 0 01.078.01c.12.098.246.198.373.292a.077.077 0 01-.006.127 12.299 12.299 0 01-1.873.892.077.077 0 00-.041.107c.36.698.772 1.362 1.225 1.993a.076.076 0 00.084.028 19.839 19.839 0 006.002-3.03.077.077 0 00.032-.054c.5-5.177-.838-9.674-3.549-13.66a.061.061 0 00-.031-.03zM8.02 15.33c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.956-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.956 2.418-2.157 2.418zm7.975 0c-1.183 0-2.157-1.085-2.157-2.419 0-1.333.955-2.419 2.157-2.419 1.21 0 2.176 1.096 2.157 2.42 0 1.333-.946 2.418-2.157 2.418z\"/></svg>Discord</button>\n    </div>\n\n    <p style=\"text-align:center;font-size:13px;color:rgba(0,0,0,0.4);margin:0\">\n      还没有账号？<a href=\"sign-up.html\" style=\"color:#6BAFDF;font-weight:600;text-decoration:none\">注册</a>\n    </p>\n  </div>\n</div>\n\n<footer style=\"padding:28px;text-align:center;background:#f5f1ea;border-top:1px solid rgba(0,0,0,0.06);font-size:11px;color:rgba(0,0,0,0.3);letter-spacing:0.06em\">© 2026 幻 MIRAX API · 开源 AI 网关</footer>",
