  "users-mgmt": {
    "file": "users-mgmt.html",
    "title": "用户管理 — 幻 MIRAX API",
    "html": "<style>body{overflow:hidden}.app{display:flex;height:100vh;background:#fafaf9}\n.sidebar{width:240px;flex-shrink:0;border-right:1px solid rgba(0,0,0,0.06);display:flex;flex-direction:column;overflow-y:auto}\n.sidebar-section{margin-bottom:4px}.sidebar-section-label{padding:10px 20px 4px;font-size:10px;font-weight:700;letter-spacing:0.1em;text-transform:uppercase;color:rgba(0,0,0,0.3)}\n.sidebar-item{display:flex;align-items:center;gap:10px;padding:8px 20px;font-size:13px;font-weight:500;color:rgba(0,0,0,0.55);text-decoration:none;transition:all 0.15s}\n.sidebar-item:hover{color:#1a1815;background:rgba(0,0,0,0.03)}.sidebar-item.active{color:#1a1815;background:rgba(0,0,0,0.05);font-weight:600}\n.sidebar-item .dot{width:6px;height:6px;border-radius:50%;flex-shrink:0}\n.main-area{flex:1;display:flex;flex-direction:column;min-width:0;overflow:hidden}\n.topbar{height:48px;flex-shrink:0;border-bottom:1px solid rgba(0,0,0,0.06);display:flex;align-items:center;padding:0 20px;gap:12px;background:#fafaf9}\n.topbar-toggle{cursor:pointer;padding:4px;border-radius:6px;border:none;background:transparent;font-size:16px;line-height:1;color:rgba(0,0,0,0.5);font-family:inherit}.topbar-toggle:hover{color:#1a1815}.topbar-brand{font-weight:800;font-size:13px;letter-spacing:-0.02em}\n.page{flex:1;overflow-y:auto;padding:24px 28px}.page-title{font-family:'Noto Serif SC','Playfair Display',Georgia,serif;font-size:1.5rem;font-weight:700}\n.card-sm{padding:20px;background:rgba(0,0,0,0.02);border:1px solid rgba(0,0,0,0.05);border-radius:14px}.badge{padding:3px 8px;border-radius:4px;font-size:10px;font-weight:600;letter-spacing:0.04em;white-space:nowrap;display:inline-block}\n.quick-btn{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;border:1px solid rgba(0,0,0,0.08);border-radius:8px;font-size:12px;font-weight:500;cursor:pointer;background:#fff;color:rgba(0,0,0,0.6);text-decoration:none;font-family:inherit;transition:all 0.2s}\n.quick-btn:hover{border-color:rgba(0,0,0,0.2);color:#1a1815}\n</style>\n<div class=\"app\">\n<aside class=\"sidebar\"><div style=\"padding:14px 20px;font-weight:800;font-size:13px;letter-spacing:-0.02em;border-bottom:1px solid rgba(0,0,0,0.05);margin-bottom:4px\"><a href=\"index.html\" class=\"brand-scan\" style=\"color:inherit;text-decoration:none\">幻 MIRAX API</a></div>\n<div class=\"sidebar-section\"><div class=\"sidebar-section-label\">General</div><a href=\"dashboard.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#6BAFDF\"></span>总览</a><a href=\"keys.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#4DB899\"></span>API Keys</a><a href=\"logs.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#6BAFDF\"></span>用量日志</a></div>\n<div class=\"sidebar-section\"><div class=\"sidebar-section-label\">Personal</div><a href=\"wallet.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#4DB899\"></span>钱包</a><a href=\"profile.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#C4B89A\"></span>个人资料</a></div>\n<div class=\"sidebar-section\"><div class=\"sidebar-section-label\">Admin</div><a href=\"channels.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#E8702A\"></span>渠道管理</a><a href=\"models-mgmt.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#6BAFDF\"></span>模型管理</a><a href=\"users-mgmt.html\" class=\"sidebar-item active\"><span class=\"dot\" style=\"background:#4DB899\"></span>用户管理</a><a href=\"settings.html\" class=\"sidebar-item\"><span class=\"dot\" style=\"background:#C4B89A\"></span>系统设置</a></div></aside>\n<div class=\"main-area\"><div class=\"topbar\"><button class=\"topbar-toggle\" onclick=\"document.getElementById('sidebar').classList.toggle('collapsed')\">☰</button><div class=\"topbar-brand brand-scan\">幻 MIRAX API</div> <a href=\"index.html\" style=\"font-size:11px;color:rgba(0,0,0,0.4);text-decoration:none;font-weight:500\">← 首页</a><div style=\"margin-left:auto;display:flex;gap:8px\"><a href=\"settings.html\" class=\"quick-btn\">设置</a><a href=\"profile.html\" class=\"quick-btn\">个人</a></div></div>\n<div class=\"page\">\n<h1 class=\"page-title\" style=\"margin-bottom:20px\">用户管理</h1>\n<div class=\"card-sm\" style=\"padding:0;overflow-x:auto\"><table style=\"width:100%;border-collapse:collapse;font-size:13px;min-width:700px\">\n<thead><tr style=\"border-bottom:1px solid rgba(0,0,0,0.06);text-align:left\"><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">ID</th><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">用户名</th><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">邮箱</th><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">角色</th><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">余额</th><th style=\"padding:12px 10px;font-size:10px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:rgba(0,0,0,0.35)\">状态</th></tr></thead>\n<tbody id=\"tb\"></tbody></table></div>\n</div></div></div>",
    "externalScripts": [],
    "scripts": [
      "const u=[{id:1,name:'admin',email:'admin@newapi.pro',role:'超级管理员',balance:'∞',s:'active'},{id:2,name:'devteam',email:'dev@company.com',role:'管理员',balance:'¥1,247.83',s:'active'},{id:3,name:'ailab',email:'lab@uni.edu',role:'普通用户',balance:'¥580.20',s:'active'},{id:4,name:'startupx',email:'founder@startupx.io',role:'普通用户',balance:'¥203.45',s:'frozen'}];\ndocument.getElementById('tb').innerHTML=u.map(r=>`<tr style=\"border-bottom:1px solid rgba(0,0,0,0.03)\"><td style=\"padding:10px;font-family:'JetBrains Mono',monospace;font-size:11px;color:rgba(0,0,0,0.4)\">${r.id}</td><td style=\"padding:10px;font-weight:600\">${r.name}</td><td style=\"padding:10px;color:rgba(0,0,0,0.45)\">${r.email}</td><td style=\"padding:10px\"><span class=\"badge\" style=\"background:${r.role==='超级管理员'?'rgba(232,112,42,0.08)':r.role==='管理员'?'rgba(107,175,223,0.08)':'rgba(0,0,0,0.04)'};color:${r.role==='超级管理员'?'#E8702A':r.role==='管理员'?'#6BAFDF':'rgba(0,0,0,0.5)'}\">${r.role}</span></td><td style=\"padding:10px;font-family:'JetBrains Mono',monospace;font-size:12px\">${r.balance}</td><td style=\"padding:10px\"><span class=\"badge\" style=\"background:${r.s==='active'?'rgba(77,184,153,0.08)':'rgba(196,184,154,0.12)'};color:${r.s==='active'?'#4DB899':'#C4B89A'}\">● ${r.s==='active'?'活跃':'已冻结'}</span></td></tr>`).join('');"
    ]
  },
