      "const t=[['2026-06-12','API 消耗','-$23.45','¥3,241.55'],['2026-06-10','充值','+$500.00','¥3,265.00'],['2026-06-08','赠送','+$200.00','¥2,765.00'],['2026-06-05','API 消耗','-¥87.32','¥2,565.00'],['2026-06-01','充值','+$1,000.00','¥2,652.32']];\ndocument.getElementById('tb').innerHTML=t.map(r=>`<tr style=\"border-bottom:1px solid rgba(0,0,0,0.03)\"><td style=\"padding:10px;color:rgba(0,0,0,0.45)\">${r[0]}</td><td style=\"padding:10px;font-weight:600\">${r[1]}</td><td style=\"padding:10px;font-family:'JetBrains Mono',monospace;font-size:12px;color:${r[2].startsWith('-')?'#E8702A':'#4DB899'}\">${r[2]}</td><td style=\"padding:10px;font-family:'JetBrains Mono',monospace;font-size:12px\">${r[3]}</td></tr>`).join('');"
